INSERT INTO public.products (id, slug, category_id, brand_id, name, description, badge, image_url, images, specs, specifications, needs, colors, promotion, status, sort_order)
VALUES
  ('air-13', 'air-13', 'laptop', 'apple', 'MacBook Air 13 inch', 'Gọn nhẹ để mang theo. Không gian làm việc rộng mở để học tập, xử lý công việc và bắt đầu những ý tưởng mới.', 'Mỏng nhẹ mỗi ngày', '/images/macbook-air.jpg', '[]'::jsonb, '["Apple silicon","16GB RAM","256GB SSD"]'::jsonb, '[]'::jsonb, ARRAY['study', 'work']::text[], ARRAY['Xanh']::text[], true, 'active', 0),
  ('iphone-pro', 'iphone-pro', 'phone', 'apple', 'iPhone 17 Pro', 'Ghi lại góc nhìn của bạn. Trải nghiệm điện thoại với hệ thống camera linh hoạt và không gian lưu trữ cho những điều đáng nhớ.', 'Dành cho sáng tạo', '/images/iphone-pro.jpg', '["/images/iphone-pro.jpg","/images/iphone-pro-transparent.png"]'::jsonb, '["256GB","Camera Pro","Màu cam"]'::jsonb, '[]'::jsonb, ARRAY['creative', 'work']::text[], ARRAY['Cam']::text[], false, 'active', 1),
  ('pro-14', 'pro-14', 'laptop', 'apple', 'MacBook Pro 14 inch', 'Không gian cho những dự án lớn. Một lựa chọn cho lập trình, thiết kế và quy trình sáng tạo cần hiệu năng bền bỉ.', 'Hiệu năng chuyên nghiệp', '/images/macbook-pro.jpg', '[]'::jsonb, '["Apple silicon","24GB RAM","512GB SSD"]'::jsonb, '[]'::jsonb, ARRAY['creative', 'work']::text[], ARRAY['Đen']::text[], false, 'active', 2),
  ('rtx-5090', 'rtx-5090', 'pc', 'nvidia', 'GeForce RTX 5090', 'Mảnh ghép hiệu năng cho bộ máy của bạn. Hãy kiểm tra nguồn điện, kích thước case và khả năng tương thích trước khi chọn nâng cấp.', 'Nâng tầm bộ máy', '/images/gpu.jpg', '[]'::jsonb, '["32GB GDDR7","PCIe","Card đồ họa"]'::jsonb, '[]'::jsonb, ARRAY['game', 'creative', 'upgrade']::text[], ARRAY['Đen']::text[], false, 'active', 3),
  ('iphone-17', 'iphone-17', 'phone', 'apple', 'iPhone 17', 'Những điều thường ngày, theo cách mới. Một thiết bị gọn gàng để kết nối, giải trí và lưu giữ khoảnh khắc.', 'Màu sắc của riêng bạn', '/images/iphone.jpg', '["/images/iphone.jpg","/images/iphone-transparent.png"]'::jsonb, '["256GB","Màn hình OLED","Nhiều màu sắc"]'::jsonb, '[]'::jsonb, ARRAY['study', 'work']::text[], ARRAY['Tím', 'Trắng']::text[], true, 'active', 4),
  ('air-15', 'air-15', 'laptop', 'apple', 'MacBook Air 15 inch', 'Màn hình rộng hơn cho tài liệu, bài giảng và những trang ý tưởng. Vẫn giữ sự gọn nhẹ cho một ngày năng động.', 'Thêm không gian cảm hứng', '/images/macbook-air.jpg', '[]'::jsonb, '["Apple silicon","16GB RAM","512GB SSD"]'::jsonb, '[]'::jsonb, ARRAY['study', 'work', 'creative']::text[], ARRAY['Vàng']::text[], false, 'active', 5),
  ('asus-vivobook', 'asus-vivobook', 'laptop', 'asus', 'ASUS Vivobook 15', 'ASUS Vivobook 15: sản phẩm mẫu để thử tìm kiếm, bộ lọc và giỏ hàng. Cấu hình, giá và tồn kho dưới đây là dữ liệu giả lập, không phải thông tin chào bán.', 'Lựa chọn tham khảo', '/images/product-pending.svg', '[]'::jsonb, '["Core i5","16GB RAM","512GB SSD"]'::jsonb, '[]'::jsonb, ARRAY['study', 'work']::text[], ARRAY['Bạc']::text[], true, 'active', 6),
  ('lenovo-ideapad', 'lenovo-ideapad', 'laptop', 'lenovo', 'Lenovo IdeaPad Slim 5', 'Lenovo IdeaPad Slim 5: sản phẩm mẫu để thử tìm kiếm, bộ lọc và giỏ hàng. Cấu hình, giá và tồn kho dưới đây là dữ liệu giả lập, không phải thông tin chào bán.', 'Lựa chọn tham khảo', '/images/product-pending.svg', '[]'::jsonb, '["Ryzen 5","16GB RAM","512GB SSD"]'::jsonb, '[]'::jsonb, ARRAY['study', 'work']::text[], ARRAY['Xám']::text[], false, 'active', 7),
  ('dell-inspiron', 'dell-inspiron', 'laptop', 'dell', 'Dell Inspiron 14', 'Dell Inspiron 14: sản phẩm mẫu để thử tìm kiếm, bộ lọc và giỏ hàng. Cấu hình, giá và tồn kho dưới đây là dữ liệu giả lập, không phải thông tin chào bán.', 'Lựa chọn tham khảo', '/images/product-pending.svg', '[]'::jsonb, '["Core i7","16GB RAM","512GB SSD"]'::jsonb, '[]'::jsonb, ARRAY['work']::text[], ARRAY['Bạc']::text[], false, 'active', 8),
